(() => {
 const $=id=>document.getElementById(id),read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
 const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{$('status').textContent='Browser storage is unavailable. Nothing was saved.';return false}};
 const data=anansiFrontend.normalize(anansiFrontend.read()||{works:[],shows:[],artists:[],leads:[]});
 let guest=read('anansiVisitor',{name:'Guest',id:crypto.randomUUID()});guest.id??=crypto.randomUUID();save('anansiVisitor',guest);
 const demo=[0,1,2].map(i=>({id:'demo-panel-'+i,name:'Tidal Intervals / '+(i+1),artist:'Presentation collection',show:'Tidal Intervals',format:'Painting',panel:i,image:'assets/tidal-intervals.png',story:'AI-generated presentation study. Real artist submissions will replace it.',price:'Demo · not for sale',demo:true}));
 const works=[...data.works.filter(w=>w.placement!=='Storage / unplaced'&&anansiFrontend.visible(w,data)),...demo];let selected,savedOnly=false;
 for(const title of new Set(works.map(w=>w.show||'Exhibition not assigned'))){const option=document.createElement('option');option.value=title;option.textContent=title;$('exhibitions').append(option)}
 function saved(work){const list=read('anansiSavedWorks',[]);return list.includes(work.id)||list.includes(work.name)}
 function image(work){if(!work.image){const note=document.createElement('p');note.className='notice';note.textContent=work.format==='Sculpture'?'3D sculpture · open the gallery to view its model.':'Artwork image not supplied.';return note}const img=document.createElement('img');img.src=work.image;img.alt=work.name;img.loading='lazy';img.onerror=()=>{const note=document.createElement('p');note.textContent='Image unavailable on this device.';img.replaceWith(note)};if(Number.isInteger(work.panel)){const crop=document.createElement('div');crop.className='crop';img.style.transform=`translateX(-${work.panel*220}px)`;crop.append(img);return crop}return img}
 function open(work){selected=work;$('title').textContent=work.name;$('image').replaceChildren(image(work));$('artist').textContent=work.artist;$('meta').textContent=[work.format||'Artwork',work.price||'Price on request',work.show||'Exhibition not assigned'].join(' · ');$('story').textContent=work.story||'No story has been added yet.';$('save').textContent=saved(work)?'Remove saved work':'Save work';$('enquiry').hidden=true;$('enquiryStatus').textContent='';$('details').showModal()}
 function render(){const query=$('search').value.trim().toLowerCase(),show=$('exhibitions').value;const filtered=works.filter(w=>(!savedOnly||saved(w))&&(!show||(w.show||'Exhibition not assigned')===show)&&(w.name+' '+w.artist).toLowerCase().includes(query));$('works').replaceChildren();$('status').textContent=filtered.length?filtered.length+' works':'No matching works. Try another filter.';for(const work of filtered){const card=document.createElement('article');card.className='work';const title=document.createElement('h2');title.textContent=work.name;const artist=document.createElement('p');artist.textContent=work.artist;const button=document.createElement('button');button.textContent='Read story & details';button.onclick=()=>open(work);card.append(image(work),title,artist,button);$('works').append(card)}}
 $('back').onclick=()=>$('details').close();$('search').oninput=$('exhibitions').onchange=render;
 $('savedFilter').onclick=()=>{savedOnly=!savedOnly;$('savedFilter').setAttribute('aria-pressed',String(savedOnly));render()};
 $('save').onclick=()=>{const list=read('anansiSavedWorks',[]),next=saved(selected)?list.filter(key=>key!==selected.name&&key!==selected.id):[...list,selected.id];if(save('anansiSavedWorks',next)){$('save').textContent=saved(selected)?'Remove saved work':'Save work';render()}};
 $('interest').onclick=()=>{$('enquiry').hidden=false;$('displayName').value=guest.name==='Guest'?'':guest.name;$('displayName').focus()};
 $('enquiry').onsubmit=event=>{event.preventDefault();const name=$('displayName').value.trim();if(!name){$('displayName').setCustomValidity('Enter a display name.');$('displayName').reportValidity();return}const latest=anansiFrontend.read()||data;latest.leads??=[];latest.leads.push({id:crypto.randomUUID(),visitorId:guest.id,name,workId:selected.id,interest:selected.name,message:$('message').value.trim(),status:'New',demo:true});if(save('anansiData',latest)){$('enquiry').hidden=true;$('enquiryStatus').textContent='Interest saved on this browser without contact details.';$('message').value=''}};$('displayName').oninput=()=>$('displayName').setCustomValidity('');render();
})();
